-- AI avatars an image ad can feature. Rows with no workspace are Gooidy's own
-- library (original AI people, generated by an admin); rows with a workspace
-- are avatars its owners created, which cost credits. Files live in the
-- private "creatives" bucket and are handed out as signed URLs by the server.
create table if not exists public.avatars (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid references public.workspaces(id) on delete cascade,
  slug text unique,
  name text not null check (char_length(name) between 1 and 40),
  gender text not null check (gender in ('woman', 'man', 'nonbinary')),
  age text not null check (age in ('young', 'adult', 'mature', 'senior')),
  look text not null check (look in ('casual', 'business', 'sporty', 'elegant')),
  -- How the person looks, in words: shown to image models next to the photo.
  description text not null check (char_length(description) <= 600),
  storage_path text not null unique,
  -- Credits the workspace paid to create it (0 for the library).
  credits integer not null default 0 check (credits >= 0),
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  check ((workspace_id is null) = (slug is not null))
);
create index if not exists avatars_workspace_idx on public.avatars(workspace_id, created_at desc);
alter table public.avatars enable row level security;
revoke all on public.avatars from public, anon, authenticated;
grant select on public.avatars to authenticated;
grant all on public.avatars to service_role;
create policy "read library and own avatars" on public.avatars
  for select to authenticated
  using (workspace_id is null or public.is_workspace_member(workspace_id));

-- Credit history shows avatars the workspace created.
create or replace function public.credit_activity(ws uuid, max_rows integer default 30)
returns table (
  happened_at timestamptz,
  kind text,          -- image_ads, video_ads, redo, avatar, plan, pack, free or adjust
  credits integer,    -- added (positive) or used (negative)
  product text,       -- the product an ad run was for
  status text         -- an ad run's status
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if ws is null or not public.is_workspace_member(ws) then
    raise exception 'Not a member of this workspace' using errcode = '42501';
  end if;
  return query
  select a.happened_at, a.kind, a.credits, a.product, a.status
  from (
    -- Ad runs: the charge, less what was returned and any free redo.
    select g.created_at as happened_at,
           case when fr.generation_id is not null then 'redo' else g.type end as kind,
           case when g.status = 'failed' then 0
                else -greatest(0, coalesce(c.amount, g.cost_credits)
                                  - coalesce(r.amount, 0)
                                  - coalesce(fr.credits, 0))
           end::integer as credits,
           p.name as product,
           g.status::text as status
    from public.generations g
    left join private.generation_credit_ledger c
      on c.generation_id = g.id and c.kind = 'charge'
    left join private.generation_credit_ledger r
      on r.generation_id = g.id and r.kind = 'refund'
    left join private.free_redos fr on fr.generation_id = g.id
    left join public.products p on p.id = g.product_id
    where g.workspace_id = ws
    union all
    select av.created_at, 'avatar', -av.credits, av.name, null
    from public.avatars av
    where av.workspace_id = ws and av.credits > 0
    union all
    select pg.created_at, 'plan', pg.credits, null, null
    from public.plan_credit_grants pg
    where pg.workspace_id = ws and pg.credits > 0
    union all
    select cp.created_at, 'pack', cp.credits, null, null
    from public.credit_purchases cp
    where cp.workspace_id = ws
    union all
    select ag.created_at, 'adjust', ag.amount, null, null
    from private.admin_credit_grants ag
    where ag.workspace_id = ws and ag.amount <> 0
    union all
    select tc.claimed_at, 'free', 100, null, null
    from private.trial_credit_claims tc
    join public.workspaces w on w.owner_id = tc.user_id
    where w.id = ws
  ) a
  order by a.happened_at desc
  limit least(greatest(coalesce(max_rows, 30), 1), 100);
end;
$$;

-- Credits used lately counts avatars too.
create or replace function public.credits_used_recently(ws uuid, days integer default 30)
returns integer
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if ws is null or not public.is_workspace_member(ws) then
    raise exception 'Not a member of this workspace' using errcode = '42501';
  end if;
  return coalesce((
    select sum(greatest(0, coalesce(c.amount, g.cost_credits)
                           - coalesce(r.amount, 0)
                           - coalesce(fr.credits, 0)))
    from public.generations g
    left join private.generation_credit_ledger c
      on c.generation_id = g.id and c.kind = 'charge'
    left join private.generation_credit_ledger r
      on r.generation_id = g.id and r.kind = 'refund'
    left join private.free_redos fr on fr.generation_id = g.id
    where g.workspace_id = ws and g.created_at >= now() - make_interval(days => greatest(coalesce(days, 30), 1)) and g.status <> 'failed'
  ), 0)::integer + coalesce((
    select sum(av.credits) from public.avatars av
    where av.workspace_id = ws and av.created_at >= now() - make_interval(days => greatest(coalesce(days, 30), 1))
  ), 0)::integer;
end;
$$;

revoke execute on function public.credit_activity(uuid, integer) from public, anon;
revoke execute on function public.credits_used_recently(uuid, integer) from public, anon;
grant execute on function public.credit_activity(uuid, integer) to authenticated, service_role;
grant execute on function public.credits_used_recently(uuid, integer) to authenticated, service_role;
